function numberOfGoodSubarraySplits(nums) {
  const MOD = 1_000_000_007;
  let ways = 1;
  let previous = -1;

  for (let i = 0; i < nums.length; i++) {
    if (nums[i] === 1) {
      if (previous !== -1) {
        ways = (ways * (i - previous)) % MOD;
      }
      previous = i;
    }
  }
  return previous === -1 ? 0 : ways;
}

