function numberOfGoodSubarraySplits(nums) {
  // count[i] = ways to cut the first i elements into pieces with exactly one 1 each.
  const MOD = 1000000007;
  const n = nums.length;
  const count = new Array(n + 1).fill(0);
  count[0] = 1;
  for (let end = 1; end <= n; end++) {
    let ones = 0;
    for (let start = end - 1; start >= 0; start--) {
      ones += nums[start];
      if (ones > 1) break;
      if (ones === 1) count[end] = (count[end] + count[start]) % MOD;
    }
  }
  return count[n];
}

