function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  // Vary the density of 1s: sparse arrays give long gaps, dense ones give many short gaps.
  const densities = [0, 0.05, 0.3, 0.6, 0.95];
  const density = size === 'large' ? densities[1 + Math.floor(rand() * 4)] : densities[Math.floor(rand() * densities.length)];
  return [Array.from({ length: n }, () => (rand() < density ? 1 : 0))];
}
